package com.example.editor.remote.auth.provider;

import java.net.URI;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.stereotype.Component;
import com.example.editor.remote.auth.*;
import com.example.editor.remote.storage.RemoteStorageProperties;
import com.example.editor.remote.storage.RemoteStorageProviderType;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.ObjectMapper;

/** OAuth 2.0 Authorization Code + PKCE para Dropbox. */
@Component
public class DropboxOAuthProvider implements RemoteOAuthProvider {
    private final RemoteOAuthHttpClient http;private final ObjectMapper mapper;
    /** Descripción: Inicializa una instancia de DropboxOAuthProvider con sus dependencias y datos de entrada. Entradas: http: dato de entrada necesario para la operación; mapper: componente de conversión utilizado durante el procesamiento. Salida: deja la instancia inicializada y lista para su uso. */ public DropboxOAuthProvider(RemoteOAuthHttpClient http,ObjectMapper mapper){this.http=http;this.mapper=mapper;}
    /** Descripción: Ejecuta la operación «type» correspondiente a la responsabilidad de DropboxOAuthProvider. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ @Override public RemoteStorageProviderType type(){return RemoteStorageProviderType.DROPBOX;}
    /** Descripción: Ejecuta la operación «scopes» correspondiente a la responsabilidad de DropboxOAuthProvider. Entradas: storage: dato de entrada necesario para la operación; auth: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ @Override public List<String> scopes(RemoteStorageProperties.Profile storage,RemoteAuthProperties.Provider auth){return auth.getScopes().isEmpty()?List.of("files.content.write","files.content.read","account_info.read"):List.copyOf(auth.getScopes());}
    /** Descripción: Ejecuta la operación «authorizationUri» correspondiente a la responsabilidad de DropboxOAuthProvider. Entradas: storage: dato de entrada necesario para la operación; auth: dato de entrada necesario para la operación; redirect: dato de entrada necesario para la operación; state: dato de entrada necesario para la operación; challenge: dato de entrada necesario para la operación; scopes: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ @Override public URI authorizationUri(RemoteStorageProperties.Profile storage,RemoteAuthProperties.Provider auth,String redirect,String state,String challenge,List<String> scopes){requireClient(auth);Map<String,String> values=new LinkedHashMap<>();values.put("client_id",auth.getClientId());values.put("response_type","code");values.put("redirect_uri",redirect);values.put("state",state);values.put("scope",String.join(" ",scopes));values.put("token_access_type","offline");values.put("code_challenge",challenge);values.put("code_challenge_method","S256");return RemoteOAuthJsonSupport.uri(auth.getAuthorizationUrl()+"?"+RemoteOAuthJsonSupport.query(values));}
    /** Descripción: Ejecuta la operación «exchange» correspondiente a la responsabilidad de DropboxOAuthProvider. Entradas: storage: dato de entrada necesario para la operación; auth: dato de entrada necesario para la operación; redirect: dato de entrada necesario para la operación; code: dato de entrada necesario para la operación; verifier: dato de entrada necesario para la operación; scopes: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ @Override public RemoteCredentialMaterial exchange(RemoteStorageProperties.Profile storage,RemoteAuthProperties.Provider auth,String redirect,String code,String verifier,List<String> scopes){requireClient(auth);Map<String,String> values=new LinkedHashMap<>();values.put("client_id",auth.getClientId());values.put("grant_type","authorization_code");values.put("code",code);values.put("redirect_uri",redirect);values.put("code_verifier",verifier);if(!auth.getClientSecret().isBlank())values.put("client_secret",auth.getClientSecret());JsonNode json=RemoteOAuthProviderErrorMapper.requireSuccessJson(type(),mapper,http.postForm(RemoteOAuthJsonSupport.uri(auth.getTokenUrl()),values,Map.of("Accept","application/json")),"Dropbox token exchange");return account(auth,RemoteOAuthJsonSupport.token(type(),json,scopes,"",""));}
    /** Descripción: Ejecuta la operación «refresh» correspondiente a la responsabilidad de DropboxOAuthProvider. Entradas: storage: dato de entrada necesario para la operación; auth: dato de entrada necesario para la operación; current: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ @Override public RemoteCredentialMaterial refresh(RemoteStorageProperties.Profile storage,RemoteAuthProperties.Provider auth,RemoteCredentialMaterial current){if(!current.refreshable())return current;requireClient(auth);Map<String,String> values=new LinkedHashMap<>();values.put("client_id",auth.getClientId());values.put("grant_type","refresh_token");values.put("refresh_token",current.refreshToken());if(!auth.getClientSecret().isBlank())values.put("client_secret",auth.getClientSecret());JsonNode json=RemoteOAuthProviderErrorMapper.requireSuccessJson(type(),mapper,http.postForm(RemoteOAuthJsonSupport.uri(auth.getTokenUrl()),values,Map.of("Accept","application/json")),"Dropbox token refresh");RemoteCredentialMaterial token=RemoteOAuthJsonSupport.token(type(),json,current.scopes(),current.accountId(),current.accountLabel());if(token.refreshToken().isBlank())token=new RemoteCredentialMaterial(type(),token.accessToken(),current.refreshToken(),token.tokenType(),token.expiresAt(),token.scopes(),current.accountId(),current.accountLabel(),token.issuedAt());return token;}
    /** Descripción: Ejecuta la operación «revoke» correspondiente a la responsabilidad de DropboxOAuthProvider. Entradas: storage: dato de entrada necesario para la operación; auth: dato de entrada necesario para la operación; current: dato de entrada necesario para la operación. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ @Override public void revoke(RemoteStorageProperties.Profile storage,RemoteAuthProperties.Provider auth,RemoteCredentialMaterial current){if(current==null||current.accessToken().isBlank()||auth.getRevokeUrl().isBlank())return;RemoteOAuthHttpClient.Response response=http.postEmpty(RemoteOAuthJsonSupport.uri(auth.getRevokeUrl()),Map.of("Authorization","Bearer "+current.accessToken()));if(!response.successful()&&response.statusCode()!=401)throw new RemoteAuthException(RemoteAuthException.Reason.REMOTE_ERROR,"Dropbox token revocation failed with HTTP "+response.statusCode()+": "+response.safeText());}
    /** Descripción: Ejecuta la operación «account» correspondiente a la responsabilidad de DropboxOAuthProvider. Entradas: auth: dato de entrada necesario para la operación; token: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private RemoteCredentialMaterial account(RemoteAuthProperties.Provider auth,RemoteCredentialMaterial token){JsonNode json=RemoteOAuthJsonSupport.parse(mapper,http.postEmpty(RemoteOAuthJsonSupport.uri(auth.getAccountUrl()),Map.of("Authorization","Bearer "+token.accessToken(),"Accept","application/json")),"Dropbox account lookup");String label=json.path("name").path("display_name").asText("");if(label.isBlank())label=json.path("email").asText("Dropbox account");return RemoteOAuthJsonSupport.withAccount(token,json.path("account_id").asText(""),label);}
    /** Descripción: Valida las condiciones necesarias para «requireClient» y rechaza entradas no válidas. Entradas: auth: dato de entrada necesario para la operación. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ private void requireClient(RemoteAuthProperties.Provider auth){if(auth==null||!auth.isEnabled()||auth.getClientId().isBlank())throw new RemoteAuthException(RemoteAuthException.Reason.PROVIDER_NOT_CONFIGURED,"Dropbox OAuth requires a configured client ID");}
}
